import { createReadStream, createWriteStream } from 'node:fs';
import { mkdir, rename, rm, stat } from 'node:fs/promises';
import path from 'node:path';
import { Readable } from 'node:stream';
import { pipeline } from 'node:stream/promises';
import { RangeNotSatisfiableError, type ByteRange, type ObjectStorage } from './types';

// Keys are generated by the app (e.g. `<clipId>.m4a`), never taken from a
// request, but refuse anything that could escape `dir` anyway.
const SAFE_KEY = /^[\w-]+(\.[\w-]+)*(\/[\w-]+(\.[\w-]+)*)*$/;

export function createFsStorage(dir: string): ObjectStorage {
	function pathFor(key: string): string {
		if (!SAFE_KEY.test(key)) throw new Error(`Invalid storage key: ${key}`);
		return path.join(dir, key);
	}

	return {
		async put(key, data) {
			const target = pathFor(key);
			await mkdir(path.dirname(target), { recursive: true });
			// Write under a temporary name and rename, so a half-written file
			// is never visible under the real key.
			const partial = `${target}.${crypto.randomUUID()}.partial`;
			try {
				await pipeline(
					Readable.fromWeb(data.stream() as import('node:stream/web').ReadableStream),
					createWriteStream(partial)
				);
				await rename(partial, target);
			} catch (err) {
				await rm(partial, { force: true });
				throw err;
			}
		},

		async get(key, range) {
			const file = pathFor(key);
			let size: number;
			try {
				size = (await stat(file)).size;
			} catch (err) {
				if ((err as NodeJS.ErrnoException).code === 'ENOENT') return null;
				throw err;
			}

			const { start, end } = resolveRange(range, size);
			const stream = createReadStream(file, { start, end });
			return { body: Readable.toWeb(stream) as ReadableStream<Uint8Array>, size, start, end };
		},

		async delete(key) {
			await rm(pathFor(key), { force: true });
		}
	};
}

function resolveRange(range: ByteRange | undefined, size: number): { start: number; end: number } {
	if (!range) return { start: 0, end: Math.max(size - 1, 0) };

	if ('suffix' in range) {
		if (range.suffix <= 0 || size === 0) throw new RangeNotSatisfiableError(size);
		return { start: Math.max(size - range.suffix, 0), end: size - 1 };
	}

	if (range.start >= size || (range.end !== undefined && range.end < range.start)) {
		throw new RangeNotSatisfiableError(size);
	}
	return { start: range.start, end: Math.min(range.end ?? size - 1, size - 1) };
}
